send-request.set-body:
@{
    var b = (JObject)context.Variables["body"];
    return new JObject(
      new JProperty("run_id", (string)context.Variables["runId"]),
      new JProperty("agent", context.Request.Headers.GetValueOrDefault("x-agent","unknown")),
      new JProperty("step", context.Request.Headers.GetValueOrDefault("x-step","0")),
      new JProperty("model", (string)b["model"]),
      new JProperty("est_input_tokens", b["messages"].ToString().Length / 4),
      new JProperty("max_output_tokens", (int?)b["max_tokens"] ?? 1024),
      new JProperty("prompt_hash", (b["messages"].ToString()).GetHashCode().ToString())
    ).ToString();
  }

when.set-body:
@{
      var b = (JObject)context.Variables["body"];
      var d = (JObject)context.Variables["d"];
      if (d["model_override"] != null)  { b["model"] = (string)d["model_override"]; }
      if (d["max_output_tokens"] != null) { b["max_tokens"] = (int)d["max_output_tokens"]; }
      if (d["inject"] != null) {
        ((JArray)b["messages"]).Add(new JObject(
          new JProperty("role","system"),
          new JProperty("content",(string)d["inject"])));
      }
      if ((bool?)b["stream"] == true) {
        b["stream_options"] = new JObject(new JProperty("include_usage", true));
      }
      return b.ToString();
    }

send-one-way-request.set-body:
@{
    var r = context.Response.Body.As<JObject>(preserveContent: true);
    var u = r["usage"];
    return new JObject(
      new JProperty("run_id", (string)context.Variables["runId"]),
      new JProperty("reservation_id", (string)context.Variables["reservationId"]),
      new JProperty("input_tokens",  (int?)u?["prompt_tokens"] ?? 0),
      new JProperty("output_tokens", (int?)u?["completion_tokens"] ?? 0),
      new JProperty("model", (string)r["model"])
    ).ToString();
  }
